function(container, apiUrl, tables) {
  const tbody = container.querySelector("#order-tbody");
  const errorMessage = container.querySelector("#error-message");
  const storeSelect = container.querySelector("#select-store");
  const orderDateInput = container.querySelector("#input-order-date");
  const categorySelect = container.querySelector("#select-category");
  const totalAmountSpan = container.querySelector("#total-amount");
  const totalItemsSpan = container.querySelector("#total-items");

  let currentOrderData = [];
  let storeData = [];
  let productData = [];
  let forecastData = [];

  // エラー表示関数
  function showError(message) {
    errorMessage.textContent = message;
    errorMessage.classList.remove("hidden");
    setTimeout(() => {
      errorMessage.classList.add("hidden");
    }, 5000);
  }

  // 合計金額計算
  function calculateTotals() {
    let totalAmount = 0;
    let totalItems = 0;

    const quantityInputs = container.querySelectorAll(".order-quantity-input");
    quantityInputs.forEach(input => {
      const quantity = parseInt(input.value) || 0;
      if (quantity > 0) {
        const unitPrice = parseInt(input.dataset.unitPrice) || 0;
        totalAmount += quantity * unitPrice;
        totalItems++;
      }
    });

    totalAmountSpan.textContent = `¥${totalAmount.toLocaleString()}`;
    totalItemsSpan.textContent = `${totalItems}件`;
  }

  // 発注データ描画
  function renderOrderData(data) {
    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="10" style="text-align: center; color: var(--text-muted);">データがありません</td></tr>';
      calculateTotals();
      return;
    }

    tbody.innerHTML = data.map(item => {
      const product = productData.find(p => p.商品ID === item.商品ID) || {};
      const forecast = forecastData.find(f => f.商品ID === item.商品ID) || {};
      const orderAmount = (item.発注数量 || 0) * (item.発注単価 || 0);

      return `
        <tr data-id="${item.発注ID || ''}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${product.商品カテゴリ || ''}</td>
          <td class="quantity-cell">${forecast.予測数量 || 0}</td>
          <td class="quantity-cell">${forecast.推奨発注数量 || 0}</td>
          <td class="quantity-cell">${item.現在在庫数量 || 0}</td>
          <td>
            <input type="number" 
                   class="input order-quantity-input" 
                   value="${item.発注数量 || 0}"
                   min="0"
                   max="999999"
                   data-product-id="${item.商品ID}"
                   data-unit-price="${item.発注単価 || 0}">
          </td>
          <td class="amount-cell">¥${(item.発注単価 || 0).toLocaleString()}</td>
          <td class="amount-cell">¥${orderAmount.toLocaleString()}</td>
          <td>
            <button class="action-btn secondary edit-btn" data-id="${item.発注ID || ''}">編集</button>
          </td>
        </tr>
      `;
    }).join("");

    calculateTotals();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗データ読み込み
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storeData = stores;
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join("");
      }

      // 商品データ読み込み
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        productData = products;
      }

      // 需要予測データ読み込み
      const forecasts = await window.aivicApi.list(8); // 需要予測結果
      if (forecasts) {
        forecastData = forecasts;
      }

      // 発注データ読み込み
      const orders = await window.aivicApi.list(9); // 発注データ
      if (orders) {
        currentOrderData = orders;
        renderOrderData(orders);
      }
    } catch (error) {
      console.error("データ読み込みエラー:", error);
      showError("データの読み込みに失敗しました");
    }
  }

  // 今日の日付を設定
  const today = new Date();
  orderDateInput.value = today.toISOString().split('T')[0];

  // 表示ボタン
  container.querySelector("#btn-display").addEventListener("click", async () => {
    const storeId = storeSelect.value;
    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }

    try {
      const orders = await window.aivicApi.list(9);
      if (orders) {
        const filteredOrders = orders.filter(order => order.店舗ID === storeId);

        // カテゴリフィルター適用
        const selectedCategory = categorySelect.value;
        if (selectedCategory) {
          const filteredByCategory = filteredOrders.filter(order => {
            const product = productData.find(p => p.商品ID === order.商品ID);
            return product && product.商品カテゴリ === selectedCategory;
          });
          renderOrderData(filteredByCategory);
        } else {
          renderOrderData(filteredOrders);
        }
      }
    } catch (error) {
      showError("発注データの取得に失敗しました");
    }
  });

  // 予測結果更新ボタン
  container.querySelector("#btn-update-forecast").addEventListener("click", async () => {
    const orderDate = orderDateInput.value;
    const storeId = storeSelect.value;

    if (!orderDate) {
      showError("発注日付を選択してください");
      return;
    }

    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }

    // 過去日付チェック
    const selectedDate = new Date(orderDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (selectedDate < today) {
      showError("発注日付には本日以降の日付を選択してください");
      return;
    }

    try {
      // 需要予測データを再取得
      const forecasts = await window.aivicApi.list(8);
      if (forecasts) {
        forecastData = forecasts;
        // 現在表示中のデータを再描画
        const currentData = Array.from(tbody.querySelectorAll("tr")).map(tr => {
          const productId = tr.querySelector(".order-quantity-input")?.dataset.productId;
          return currentOrderData.find(order => order.商品ID === productId);
        }).filter(Boolean);
        renderOrderData(currentData);
      }
    } catch (error) {
      showError("予測結果の更新に失敗しました");
    }
  });

  // 推奨発注数量で一括入力
  container.querySelector("#btn-bulk-recommend").addEventListener("click", () => {
    if (!confirm("推奨発注数量で一括入力しますか？")) return;

    const quantityInputs = container.querySelectorAll(".order-quantity-input");
    quantityInputs.forEach(input => {
      const productId = input.dataset.productId;
      const forecast = forecastData.find(f => f.商品ID === productId);
      if (forecast && forecast.推奨発注数量) {
        input.value = forecast.推奨発注数量;
      }
    });
    calculateTotals();
  });

  // 承認実行
  container.querySelector("#btn-approve").addEventListener("click", async () => {
    const storeId = storeSelect.value;
    const orderDate = orderDateInput.value;

    if (!storeId) {
      showError("店舗を選択してください");
      return;
    }

    if (!orderDate) {
      showError("発注日付を選択してください");
      return;
    }

    // 過去日付チェック
    const selectedDate = new Date(orderDate);
    const today = new Date();
    today.setHours(0, 0, 0, 0);

    if (selectedDate < today) {
      showError("発注日付には本日以降の日付を選択してください");
      return;
    }

    const quantityInputs = container.querySelectorAll(".order-quantity-input");
    let hasValidOrder = false;
    let hasError = false;

    // バリデーション
    for (const input of quantityInputs) {
      const value = input.value.trim();
      const quantity = parseInt(value);

      if (value === "") {
        showError("発注数量を入力してください");
        hasError = true;
        break;
      }

      if (isNaN(quantity)) {
        showError("発注数量は数値を入力してください");
        hasError = true;
        break;
      }

      if (quantity < 0) {
        showError("発注数量は正の値を入力してください");
        hasError = true;
        break;
      }

      if (quantity > 0) {
        hasValidOrder = true;
      }
    }

    if (hasError) return;

    if (!confirm("発注内容を承認して実行しますか？")) return;

    try {
      // 発注データを保存
      const promises = [];
      quantityInputs.forEach(input => {
        const quantity = parseInt(input.value) || 0;
        const productId = input.dataset.productId;
        const unitPrice = parseInt(input.dataset.unitPrice) || 0;

        if (quantity >= 0) { // 0でも承認可能
          const orderData = {
            店舗ID: storeId,
            商品ID: productId,
            発注日: orderDate,
            発注数量: quantity,
            発注単価: unitPrice,
            発注金額: quantity * unitPrice,
            発注方法: "手動発注",
            発注ステータス: "承認済み",
            自動発注フラグ: false,
            納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString().split('T')[0] // 3日後
          };
          promises.push(window.aivicApi.save(9, orderData));
        }
      });

      await Promise.all(promises);

      // 成功メッセージ表示（エラーメッセージ要素を流用）
      errorMessage.style.background = "rgba(0, 200, 0, 0.1)";
      errorMessage.style.borderColor = "#00c800";
      errorMessage.textContent = "発注が正常に承認されました";
      errorMessage.classList.remove("hidden");

      setTimeout(() => {
        errorMessage.classList.add("hidden");
        errorMessage.style.background = "rgba(255, 106, 0, 0.1)";
        errorMessage.style.borderColor = "#ff6a00";
      }, 3000);

      // データを再読み込み
      await loadInitialData();

    } catch (error) {
      showError("発注の承認に失敗しました");
    }
  });

  // 発注数量入力時の金額計算
  container.addEventListener("input", (e) => {
    if (e.target.classList.contains("order-quantity-input")) {
      calculateTotals();
    }
  });

  // 発注数量のバリデーション
  container.addEventListener("blur", (e) => {
    if (e.target.classList.contains("order-quantity-input")) {
      const value = e.target.value.trim();
      const quantity = parseInt(value);

      if (value !== "" && (isNaN(quantity) || quantity < 0)) {
        if (isNaN(quantity)) {
          showError("発注数量は数値を入力してください");
        } else if (quantity < 0) {
          showError("発注数量は正の値を入力してください");
        }
        e.target.focus();
      }
    }
  }, true);

  // イベントデリゲーション
  container.addEventListener("click", async (e) => {
    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const orderId = editBtn.dataset.id;
      // 編集機能は発注管理画面に遷移
      window.showScreen("scr-1778591852463");
    }
  });

  // 初期データ読み込み
  loadInitialData();
}
